PRICING = {  # mock per-1M-token rates for training purposes
    "provider_a": {"input": 3.0, "output": 15.0},
    "provider_b": {"input": 2.0, "output": 8.0},
    "provider_c": {"input": 1.0, "output": 4.0},
}

WORKLOAD = {"in_tokens": 20_000_000, "out_tokens": 2_000_000}

def monthly_cost(in_tokens, out_tokens, rates):
    return (in_tokens / 1_000_000) * rates['input'] + (out_tokens / 1_000_000) * rates['output']

costs = {}
for provider, rates in PRICING.items():
    costs[provider] = monthly_cost(WORKLOAD["in_tokens"], WORKLOAD["out_tokens"], rates)
    print(f"{provider}: ${costs[provider]:.2f}")

cheapest = min(costs, key=costs.get)
priciest = max(costs, key=costs.get)
diff = costs[priciest] - costs[cheapest]
print(f"cheapest={cheapest} saves ${diff:.2f} vs {priciest}")
